import { useCallback, useRef, useState } from "react";
import type { KeyboardEvent } from "react";
import "./TimeList.css";

export type TimeState = "past" | "next" | "later";

export interface TimeItem {
  readonly name: string;
  readonly time: string;
  readonly state: TimeState;
}

export interface TimeListProps {
  readonly items: readonly TimeItem[];
  readonly onSelect?: (item: TimeItem, index: number) => void;
  readonly label?: string;
}

const STATE_WORD: Readonly<Record<TimeState, string>> = {
  past: "passed",
  next: "next",
  later: "upcoming",
};

export function TimeList({
  items,
  onSelect,
  label = "Daily times",
}: TimeListProps) {
  const nextIndex = items.findIndex((item) => item.state === "next");
  const [focusIndex, setFocusIndex] = useState<number>(
    nextIndex >= 0 ? nextIndex : 0,
  );
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);

  // Keep the roving tab stop valid if the item list shrinks.
  const activeIndex =
    items.length === 0 ? -1 : Math.min(focusIndex, items.length - 1);

  const moveTo = useCallback(
    (target: number) => {
      if (items.length === 0) return;
      const clamped = Math.min(Math.max(target, 0), items.length - 1);
      setFocusIndex(clamped);
      buttonRefs.current[clamped]?.focus();
    },
    [items.length],
  );

  const handleKeyDown = (
    event: KeyboardEvent<HTMLButtonElement>,
    index: number,
  ) => {
    switch (event.key) {
      case "ArrowDown":
      case "ArrowRight":
        event.preventDefault();
        moveTo(index + 1);
        break;
      case "ArrowUp":
      case "ArrowLeft":
        event.preventDefault();
        moveTo(index - 1);
        break;
      case "Home":
        event.preventDefault();
        moveTo(0);
        break;
      case "End":
        event.preventDefault();
        moveTo(items.length - 1);
        break;
      default:
        break;
    }
  };

  if (items.length === 0) {
    return null;
  }

  return (
    <ul className="time-list" aria-label={label}>
      {items.map((item, index) => (
        <li key={`${item.name}-${item.time}-${index}`} className="time-list__row">
          <button
            type="button"
            ref={(el) => {
              buttonRefs.current[index] = el;
            }}
            className="time-list__item"
            data-state={item.state}
            aria-current={item.state === "next" ? "time" : undefined}
            tabIndex={index === activeIndex ? 0 : -1}
            onFocus={() => setFocusIndex(index)}
            onKeyDown={(event) => handleKeyDown(event, index)}
            onClick={() => {
              setFocusIndex(index);
              onSelect?.(item, index);
            }}
          >
            <span className="time-list__time">{item.time}</span>
            <span className="time-list__name">{item.name}</span>
            <span className="time-list__state sr-only">
              {STATE_WORD[item.state]}
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
