.time-list__item[data-state="later"] {
  color: var(--time-list-ink);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: no-preference) {
  .time-list__item {
    transition: background-color 160ms ease, color 160ms ease;
  }

  .time-list__item:hover {
    background-color: color-mix(in srgb, var(--time-list-ink) 4%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .time-list__item {
    transition: none;
  }
}
